import * as THREE from './vendor/three.module.js';
import {CityWorld,createPerson,PLACES} from './world.js';
import {Terrain} from './terrain.js';
import {collides,clamp,dist,makeRoadGraph,nearestRoad} from './core.js';

const $=id=>document.getElementById(id);
const ERA_RADIUS=1500;
const CENTER={x:-180,z:30};
const state={ready:false,started:false,paused:false,mode:'foot',x:-150,z:-49,y:0,yaw:-.45,speed:0,health:100,wanted:0,elapsed:0,mount:null,camera:0};
const keys=new Set();
let scene,camera,renderer,terrain,world,data,graph,player,frameTime=0,drag=null,camYaw=-.45,camPitch=.34;
const mounts=[],npcs=[],guards=[],animals=[];

const boxGeo=new THREE.BoxGeometry(1,1,1),sphereGeo=new THREE.SphereGeometry(1,12,8),cylGeo=new THREE.CylinderGeometry(1,1,1,12),coneGeo=new THREE.ConeGeometry(1,1,12);
const mats=new Map();
function mat(color,rough=1){const k=color+rough;if(!mats.has(k))mats.set(k,new THREE.MeshStandardMaterial({color,roughness:rough}));return mats.get(k);}
function primitive(g,geo,color,x,y,z,sx,sy,sz){const m=new THREE.Mesh(geo,mat(color));m.position.set(x,y,z);m.scale.set(sx,sy,sz);m.castShadow=m.receiveShadow=true;g.add(m);return m;}
const box=(g,c,x,y,z,w,h,d)=>primitive(g,boxGeo,c,x,y,z,w,h,d);
function cylinder(g,c,x,y,z,r,h){return primitive(g,cylGeo,c,x,y,z,r,h,r);}
function sphere(g,c,x,y,z,sx,sy= sx,sz=sx){return primitive(g,sphereGeo,c,x,y,z,sx,sy,sz);}
function seeded(n){const x=Math.sin(n*129.9898+78.233)*43758.5453;return x-Math.floor(x);}
function progress(n,t){$('loadingBar').style.width=n+'%';$('loadingText').textContent=t;}
function eraDistance(p){return Math.hypot((p.cx??p.x??0)-CENTER.x,(p.cz??p.z??0)-CENTER.z);}
function roadInEra(r){return r.p?.some(p=>Math.hypot(p[0]-CENTER.x,p[1]-CENTER.z)<ERA_RADIUS+120)&&!['motorway','trunk'].includes(r.k);}
function periodData(source){return {...source,buildings:source.buildings.filter(b=>eraDistance(b)<ERA_RADIUS+80).map(b=>({...b,h:Math.min(18,Math.max(5,b.h||9)),t:'historic'})),roads:source.roads.filter(roadInEra),areas:source.areas.filter(a=>a.p?.some(p=>Math.hypot(p[0]-CENTER.x,p[1]-CENTER.z)<ERA_RADIUS+180)),water:source.water.filter(r=>r.p?.some(p=>Math.hypot(p[0]-CENTER.x,p[1]-CENTER.z)<ERA_RADIUS+180))};}

function horseMesh(color='#7a4f32',rider=false){const g=new THREE.Group();
 box(g,color,0,1.15,0,1.05,.78,2.05);sphere(g,color,0,1.42,.95,.52,.58,.65);box(g,color,0,1.75,1.25,.52,.65,.72);sphere(g,'#31271f',0,2.04,1.42,.34,.34,.42);
 for(const s of [-1,1])for(const z of [-.62,.62]){box(g,'#5a3927',s*.38,.55,z,.22,.95,.24);box(g,'#24201d',s*.38,.08,z,.27,.15,.32);}
 box(g,'#2f261f',0,1.58,-1.15,.12,.12,1.25).rotation.x=-.42;box(g,'#4a2e20',0,1.58,.18,.72,.12,.72);
 if(rider){const p=createPerson('#6c513e',3);p.scale.setScalar(.78);p.position.set(0,1.38,-.1);p.rotation.x=-.08;g.add(p);}return g;
}
function cartMesh(color='#785333'){const g=new THREE.Group();
 box(g,color,0,.83,-.25,1.65,.22,2.75);box(g,'#5e3f29',0,1.08,-.45,1.58,.72,1.75);box(g,color,-.75,1.34,-.45,.12,.72,1.8);box(g,color,.75,1.34,-.45,.12,.72,1.8);box(g,color,0,1.34,-1.3,1.55,.72,.12);
 for(const x of [-.94,.94]){const w=cylinder(g,'#3d2b20',x,.55,-.25,.58,.15);w.rotation.z=Math.PI/2;cylinder(g,'#8b6a46',x*1.01,.55,-.25,.34,.17).rotation.z=Math.PI/2;}
 for(const x of [-.48,.48])box(g,'#6f4a2f',x,.54,1.65,.11,.11,2.25);
 const h=horseMesh('#755039',false);h.scale.setScalar(.85);h.position.set(0,0,2.55);g.add(h);return g;
}
function addMount(kind,x,z,yaw=0,parked=true){const spec=kind==='horse'?{name:'Cavallo',width:1.15,length:2.35,max:14,accel:7,brake:13,steer:1.8}:{name:'Carro a cavalli',width:1.95,length:5.7,max:8,accel:3.5,brake:9,steer:.82};const mesh=kind==='horse'?horseMesh(['#744b30','#4d382c','#926642'][mounts.length%3],false):cartMesh();const m={kind,x,z,yaw,speed:0,parked,spec,mesh};mesh.position.set(x,terrain.height(x,z),z);mesh.rotation.y=yaw;scene.add(mesh);mounts.push(m);return m;}
function placeMount(m){m.y=terrain.height(m.x,m.z,m.y);m.mesh.position.set(m.x,m.y,m.z);m.mesh.rotation.y=m.yaw;}

function accessory(person,role){const add=(geo,c,x,y,z,sx,sy,sz)=>primitive(person,geo,c,x,y,z,sx,sy,sz);
 if(role==='priest'){add(coneGeo,'#25231f',0,2.02,0,.29,.23,.29);box(person,'#171717',0,1.1,0,.65,.85,.42);box(person,'#c7b27b',0,1.30,.24,.035,.34,.035);box(person,'#c7b27b',0,1.38,.24,.20,.035,.035);}
 if(role==='merchant'){box(person,'#82603f',0,1.03,.20,.58,.62,.08);box(person,'#6f472d',0,1.90,0,.56,.08,.56);}
 if(role==='artisan'){box(person,'#6d543c',0,1.90,0,.46,.10,.46);box(person,'#846a47',.34,1.12,.20,.12,.65,.08);}
 if(role==='scholar'){box(person,'#392f35',0,1.1,0,.65,.72,.42);box(person,'#2a2630',0,1.91,0,.54,.10,.54);}
 if(role==='porter'){box(person,'#73543a',0,1.04,-.29,.62,.72,.22);}
 if(role==='guard'){box(person,'#5b3028',0,1.17,0,.64,.68,.38);box(person,'#a58a61',0,1.92,0,.48,.10,.48);const sword=box(person,'#bfc3bd',.42,1.04,.05,.04,.9,.04);sword.rotation.z=-.12;box(person,'#6f4d2f',.42,.61,.05,.10,.16,.10);}
}
const roles=['merchant','priest','artisan','scholar','porter','citizen','citizen','citizen'];
function makeNPC(seed,x,z,role=null){role=role||roles[seed%roles.length];const colors={merchant:'#a3764f',priest:'#25231f',artisan:'#7a6650',scholar:'#514654',porter:'#815e45',citizen:['#8d694e','#65705e','#8a5f57'][seed%3],guard:'#6b3a31'};const p={x,z,yaw:seeded(seed)*Math.PI*2,seed,role,speed:0,anchor:{x,z},wait:seeded(seed+8)*4,mesh:createPerson(Array.isArray(colors[role])?colors[role][seed%colors[role].length]:colors[role],seed)};accessory(p.mesh,role);p.y=terrain.height(x,z);p.mesh.position.set(x,p.y,z);scene.add(p.mesh);npcs.push(p);return p;}
function makeGuard(seed,x,z,mounted=false){const g=makeNPC(500+seed,x,z,'guard');g.mounted=mounted;g.patrolRadius=18+seeded(seed)*35;guards.push(g);if(mounted){const horse=horseMesh(seed%2?'#4f382b':'#81583a',false);horse.position.y=-.05;g.mesh.add(horse);g.mesh.position.y=terrain.height(x,z);g.mesh.children.forEach((c,i)=>{if(i<1)return;});g.mesh.scale.setScalar(.9);}return g;}

function marketStall(root,x,z,yaw,cloth='#8e5945'){const g=new THREE.Group();g.position.set(x,terrain.height(x,z),z);g.rotation.y=yaw;root.add(g);for(const sx of [-1.5,1.5])for(const sz of [-.8,.8])box(g,'#6b4a30',sx,1.25,sz,.12,2.5,.12);box(g,'#715139',0,1.05,0,3.2,.16,1.8);const roof=box(g,cloth,0,2.55,0,3.5,.10,2.1);roof.rotation.z=.04;for(let i=0;i<8;i++)sphere(g,['#8a6a3e','#6f7f47','#b68b4c'][i%3],-1.2+(i%4)*.8,1.3,-.38+Math.floor(i/4)*.65,.16,.13,.16);}
function barrel(root,x,z){const b=cylinder(root,'#704c32',x,terrain.height(x,z)+.45,z,.38,.9);b.rotation.z=.03;box(root,'#3d342b',x,terrain.height(x,z)+.25,z,.8,.04,.04);box(root,'#3d342b',x,terrain.height(x,z)+.65,z,.8,.04,.04);}
function buildPeriodCity(){const root=new THREE.Group();root.name='Padova 1500';scene.add(root);
 const wall=[[-1030,-680],[-720,-1030],[-120,-1160],[520,-980],[910,-520],[900,90],[700,700],[260,1120],[-420,1080],[-940,650],[-1130,80]];
 const stone='#ad9270';for(let i=0;i<wall.length;i++){const a=wall[i],b=wall[(i+1)%wall.length],dx=b[0]-a[0],dz=b[1]-a[1],len=Math.hypot(dx,dz),yaw=Math.atan2(dx,dz),x=(a[0]+b[0])/2,z=(a[1]+b[1])/2,y=terrain.height(x,z);const seg=box(root,stone,x,y+3.4,z,2.7,6.8,len);seg.rotation.y=yaw;for(let d=-len/2+5;d<len/2;d+=7){const c=box(root,'#b59a76',x+Math.sin(yaw)*d,y+7.05,z+Math.cos(yaw)*d,3.2,1.1,3.2);c.rotation.y=yaw;}if(i%2===0){cylinder(root,'#9b8061',a[0],terrain.height(a[0],a[1])+5.5,a[1],5.5,11);primitive(root,coneGeo,'#7f654d',a[0],terrain.height(a[0],a[1])+13,a[1],7,4,7);}}
 const gates=[[-958,-650,1.0],[-760,650,2.35],[650,700,-2.4],[520,-970,-.55]];for(const [x,z,yaw] of gates){const g=new THREE.Group();g.position.set(x,terrain.height(x,z),z);g.rotation.y=yaw;root.add(g);box(g,'#9e805f',-5,5,0,6,10,8);box(g,'#9e805f',5,5,0,6,10,8);box(g,'#5a4938',0,2.8,0,4.5,5.6,2);for(const s of [-1,1])primitive(g,coneGeo,'#785e49',s*5,12,0,4.2,4.5,4.2);}
 const market=[[-190,-40,0,'#91523e'],[-150,-5,.1,'#8a6b3f'],[-105,-45,-.1,'#5d7055'],[-245,-85,.15,'#6e4f74'],[-300,-125,0,'#9a7147'],[-260,-165,.2,'#6b7754']];for(const s of market)marketStall(root,...s);for(let i=0;i<18;i++)barrel(root,-300+seeded(i)*260,-180+seeded(i+2)*230);
 // Timber piles, wells and simple roadside workshops.
 for(let i=0;i<20;i++){const x=-650+seeded(i+20)*1200,z=-620+seeded(i+40)*1200;if(Math.hypot(x-CENTER.x,z-CENTER.z)>950)continue;const y=terrain.height(x,z);for(let j=0;j<4;j++){const log=cylinder(root,'#765238',x+j*.28,y+.18+j*.15,z,.13,2.2);log.rotation.z=Math.PI/2;}}
 const well=new THREE.Group();well.position.set(-330,terrain.height(-330,-20),-20);root.add(well);cylinder(well,'#8f806d',0,.55,0,1.2,1.1);box(well,'#6b4a31',-1.35,1.8,0,.14,2.8,.14);box(well,'#6b4a31',1.35,1.8,0,.14,2.8,.14);box(well,'#6b4a31',0,3.0,0,3,.14,.14);
 return root;
}
function createAnimal(type,seed,x,z){const g=new THREE.Group(),small=type==='chicken';if(type==='goat'){box(g,'#c3b292',0,.62,0,.7,.55,1.15);sphere(g,'#b6a788',0,.88,.55,.32,.34,.4);for(const s of [-1,1])box(g,'#654f3c',s*.18,.27,.1,.12,.55,.12);}else if(type==='pig'){box(g,'#b77c73',0,.48,0,.8,.55,1.2);sphere(g,'#c48a80',0,.59,.62,.38,.35,.42);for(const s of [-1,1])box(g,'#7d5e54',s*.26,.19,.05,.12,.38,.12);}else{sphere(g,'#d8d1b6',0,.27,0,.24,.28,.32);sphere(g,'#c45134',0,.32,.25,.13,.14,.15);for(const s of [-1,1])box(g,'#7b5a32',s*.08,.08,0,.025,.18,.025);}const a={type,seed,x,z,yaw:seeded(seed)*6.28,mesh:g,anchor:{x,z},speed:small?.45:.6};g.position.set(x,terrain.height(x,z),z);scene.add(g);animals.push(a);}
function populate(){addMount('horse',-125,-5,.3,true);addMount('cart',-220,-110,-.4,true);for(let i=0;i<8;i++)addMount(i%3?'horse':'cart',-520+seeded(i)*950,-500+seeded(i+13)*900,seeded(i+7)*6.28,true);
 const roleSpots={merchant:[-170,-55],priest:[-350,-10],scholar:[-90,-170],artisan:[-430,130],porter:[-240,-90],citizen:[-150,40]};for(let i=0;i<56;i++){const role=roles[i%roles.length],base=roleSpots[role]||roleSpots.citizen,x=base[0]+(seeded(i+1)-.5)*(role==='citizen'?900:150),z=base[1]+(seeded(i+50)-.5)*(role==='citizen'?900:150);makeNPC(i,x,z,role);}const gateSpots=[[-950,-650],[-750,630],[650,680],[500,-930],[-280,-130],[230,540]];gateSpots.forEach((p,i)=>makeGuard(i,p[0],p[1],i%2===0));for(let i=0;i<22;i++){const type=['chicken','goat','pig'][i%3];createAnimal(type,i,-350+seeded(i+90)*700,-250+seeded(i+120)*620);}}

function nearestMount(){let best=null,d=5;for(const m of mounts){const dd=dist(state,m);if(m.parked&&dd<d){d=dd;best=m;}}return best;}
function toggleMount(){if(state.mode!=='foot'){const m=state.mount;m.parked=true;m.speed=0;state.mode='foot';state.x+=Math.cos(state.yaw)*1.6;state.z-=Math.sin(state.yaw)*1.6;state.mount=null;player.visible=true;toast('A piedi. Avvicinati a un cavallo o a un carro e premi E.');return;}const m=nearestMount();if(!m){toast('Nessun cavallo o carro abbastanza vicino.');return;}state.mode=m.kind;state.mount=m;m.parked=false;state.x=m.x;state.z=m.z;state.yaw=m.yaw;state.speed=0;player.visible=false;toast(m.kind==='horse'?'In sella. WASD per cavalcare.':'Sul carro. WASD per guidare.');}
function toast(text,sec=4){$('toast').textContent=text;$('toast').hidden=false;$('toast').dataset.until=String(state.elapsed+sec);}
function validMove(x,z,r=.4){return Math.hypot(x-CENTER.x,z-CENTER.z)<ERA_RADIUS+90&&!collides(x,z,r,world.collision)&&terrain.dry(x,z,r);}
function movePlayer(dt){const f=(keys.has('KeyW')||keys.has('ArrowUp')?1:0)-(keys.has('KeyS')||keys.has('ArrowDown')?1:0),turn=(keys.has('KeyA')||keys.has('ArrowLeft')?1:0)-(keys.has('KeyD')||keys.has('ArrowRight')?1:0);
 if(state.mode==='foot'){const sprint=keys.has('ShiftLeft')||keys.has('ShiftRight'),speed=sprint?5.8:3.2,dx=(Math.sin(camYaw)*f-Math.cos(camYaw)*turn)*speed*dt,dz=(Math.cos(camYaw)*f+Math.sin(camYaw)*turn)*speed*dt,nx=state.x+dx,nz=state.z+dz;if(validMove(nx,state.z))state.x=nx;if(validMove(state.x,nz))state.z=nz;if(Math.abs(dx)+Math.abs(dz)>.001)state.yaw=Math.atan2(dx,dz);state.speed=Math.hypot(dx,dz)/Math.max(dt,.001);state.y=terrain.height(state.x,state.z);player.position.set(state.x,state.y+.08,state.z);player.rotation.y=state.yaw;}
 else{const m=state.mount,spec=m.spec,desired=f>0?spec.max:f<0?-spec.max*.28:0;m.speed+=(desired-m.speed)*Math.min(1,dt*(f?spec.accel:spec.brake)*.35);if(keys.has('Space'))m.speed*=Math.exp(-8*dt);m.yaw+=turn*spec.steer*dt*(m.speed>=0?1:-1)*clamp(Math.abs(m.speed)/4,.25,1);const nx=m.x+Math.sin(m.yaw)*m.speed*dt,nz=m.z+Math.cos(m.yaw)*m.speed*dt;if(validMove(nx,nz,spec.width/2)){m.x=nx;m.z=nz;}else m.speed*=.15;placeMount(m);state.x=m.x;state.z=m.z;state.yaw=m.yaw;state.speed=m.speed;state.y=m.y;}
}
function updateNPCs(dt){for(const p of npcs){const d=dist(p,state),isGuard=p.role==='guard';if(isGuard&&state.wanted>0){const goal=Math.atan2(state.x-p.x,state.z-p.z);p.yaw+=clamp(((goal-p.yaw+Math.PI*3)%(Math.PI*2))-Math.PI,-2.2*dt,2.2*dt);p.speed=p.mounted?6.5:3.8;if(d<2.2){state.health=Math.max(0,state.health-12*dt);if(state.health<=0){state.wanted=0;state.health=100;state.x=-150;state.z=-49;if(state.mount){state.mount.parked=true;state.mount=null;state.mode='foot';player.visible=true;}toast('Le guardie ti hanno preso. Sei stato riportato in Piazza delle Erbe.',6);}}}else{p.wait-=dt;if(p.wait<=0){p.wait=1.5+seeded(Math.floor(state.elapsed)+p.seed)*4;p.yaw+=(-.8+seeded(p.seed+Math.floor(state.elapsed))*1.6);}p.speed={merchant:.25,priest:.65,artisan:.45,scholar:.8,porter:1.1,citizen:.9,guard:1.05}[p.role]||.8;}
 const nx=p.x+Math.sin(p.yaw)*p.speed*dt,nz=p.z+Math.cos(p.yaw)*p.speed*dt,limit=isGuard?(p.patrolRadius||45):({merchant:9,priest:45,artisan:12,scholar:65,porter:80,citizen:110}[p.role]||60);if((isGuard&&state.wanted>0)||Math.hypot(nx-p.anchor.x,nz-p.anchor.z)<limit){if(validMove(nx,nz,.35)){p.x=nx;p.z=nz;}else p.yaw+=Math.PI;}else p.yaw=Math.atan2(p.anchor.x-p.x,p.anchor.z-p.z);p.y=terrain.height(p.x,p.z);p.mesh.position.set(p.x,p.y,p.z);p.mesh.rotation.y=p.yaw;const hips=p.mesh.userData.hips;if(hips){const a=Math.sin(state.elapsed*5+p.seed)*.28;hips.children[0].rotation.x=a;hips.children[1].rotation.x=-a;}
 if(state.mode!=='foot'&&d<1.8&&Math.abs(state.speed)>4.5&&!isGuard){state.wanted=Math.max(1,state.wanted);toast('Hai travolto qualcuno: le guardie sono state allertate.',4);}}
}
function updateAnimals(dt){for(const a of animals){if(seeded(a.seed+Math.floor(state.elapsed/4))>.65)a.yaw+=dt*.5;const nx=a.x+Math.sin(a.yaw)*a.speed*dt,nz=a.z+Math.cos(a.yaw)*a.speed*dt;if(Math.hypot(nx-a.anchor.x,nz-a.anchor.z)<18&&validMove(nx,nz,.22)){a.x=nx;a.z=nz;}else a.yaw+=Math.PI*.7;a.mesh.position.set(a.x,terrain.height(a.x,a.z),a.z);a.mesh.rotation.y=a.yaw;}}
function updateCamera(dt){if(!state.started){const a=state.elapsed*.04;camera.position.set(-180+Math.sin(a)*105,90,-45+Math.cos(a)*105);camera.lookAt(-180,8,-45);return;}const d=state.mode==='foot'?6.2:state.mode==='horse'?9:13,h=state.mode==='foot'?3.1:state.mode==='horse'?4.7:6.2,anchorY=state.y+(state.mode==='foot'?1.55:1.8),angle=camYaw;const target=new THREE.Vector3(state.x-Math.sin(angle)*d,state.y+h+Math.sin(camPitch)*3,state.z-Math.cos(angle)*d);camera.position.lerp(target,1-Math.exp(-dt*9));camera.lookAt(state.x,anchorY,state.z);}
function updateUI(){const road=nearestRoad(state,graph),nearest=PLACES.reduce((a,b)=>dist(a,state)<dist(b,state)?a:b);$('location').textContent=dist(nearest,state)<180?nearest.name:road?.segment.road.n||'Padova entro le mura';$('district').textContent='PADOVA · ANNO 1500';$('wanted').textContent='⚔'.repeat(state.wanted)+'·'.repeat(Math.max(0,3-state.wanted));$('money').parentElement.innerHTML='<span id="money">1500</span> AD';$('vehicleName').textContent=state.mode==='foot'?'A PIEDI':state.mode==='horse'?'CAVALLO':'CARRO';$('speed').textContent=String(Math.round(Math.abs(state.speed)*3.6)).padStart(2,'0');$('gear').textContent=state.mode==='foot'?'—':state.speed<-.2?'R':state.speed>.2?'↑':'N';$('rpmValue').textContent=state.mode==='foot'?'—':state.mode==='horse'?'GALOPPO':'ANDATURA';$('rpm').style.width=Math.min(100,Math.abs(state.speed)/(state.mount?.spec.max||6)*100)+'%';$('altitude').textContent=Math.round(terrain.elevation(state.x,state.z))+' M';$('gradient').textContent='—';$('odometer').textContent='ANNO 1500';$('heading').textContent=['S','SE','E','NE','N','NW','W','SW'][Math.round((((state.yaw%(Math.PI*2))+Math.PI*2)%(Math.PI*2))/(Math.PI/4))%8];$('trafficLevel').textContent=npcs.filter(n=>dist(n,state)<120).length>10?'MERCATO':'QUIETO';$('healthLabel').textContent=state.mode==='foot'?'SHIFT · CORRI':'CONDIZIONE';$('healthValue').textContent=Math.round(state.health)+'%';$('health').style.width=state.health+'%';let hint='';if(state.mode==='foot'){const m=nearestMount();if(m)hint='E · '+(m.kind==='horse'?'Sali a cavallo':'Sali sul carro');}else hint='E · Scendi';$('interact').textContent=hint;$('interact').hidden=!hint;if(Number($('toast').dataset.until||0)<state.elapsed)$('toast').hidden=true;$('missionType').textContent=state.wanted?'RICERCATO DALLE GUARDIE':'VITA IN CITTÀ';$('missionTitle').textContent=state.wanted?'Fuggi dalle guardie.':'Padova, anno 1500.';$('missionDesc').textContent=state.wanted?'Soldati a piedi e a cavallo ti stanno cercando. Allontanati e resta fuori dalla loro vista.':'Esplora mercati, mura, botteghe e piazze. Cavalli e carri possono essere usati.';}
function simulate(dt){state.elapsed+=dt;if(state.started){movePlayer(dt);updateNPCs(dt);updateAnimals(dt);if(state.wanted&&guards.every(g=>dist(g,state)>150)){state.wanted=0;toast('Hai seminato le guardie.',4);}}updateCamera(dt);updateUI();world.update(state.x,state.z);}
function animate(t){requestAnimationFrame(animate);const dt=frameTime?Math.min(.05,(t-frameTime)/1000):1/60;frameTime=t;if(!state.ready)return;if(!state.paused)simulate(dt);renderer.render(scene,camera);}
function start(){if(!state.ready||state.started)return;state.started=true;$('intro').hidden=true;$('playingUI').hidden=false;toast('Padova 1500. WASD per muoverti, E per cavalli e carri, Shift per correre.',7);}
function setupIntro(){document.body.classList.add('era-1500');document.querySelector('.wordmark').innerHTML='PADOVA<span>MODALITÀ GALILEO</span>';document.querySelector('.edition').lastChild.textContent=' UNA CITTÀ DI MURA, MERCATI E CAVALLI.';document.querySelector('h1').innerHTML='PADOVA<span>GALILEO.</span>';document.querySelector('.intro p').textContent='Entra nella città rinascimentale.';$('playBtn').textContent='Entra in modalità Galileo →';$('playBtn').onclick=start;const other=$('play1500Btn');if(other){other.textContent='Torna alla Padova attuale';other.disabled=false;other.onclick=()=>location.href=location.pathname;}$('activityBtn').hidden=true;$('mapBtn').hidden=true;$('vehicleMenuBtn').hidden=true;document.querySelector('.keybar').innerHTML='<span><kbd>W A S D</kbd> muoviti</span><span><kbd>E</kbd> cavallo / carro</span><span><kbd>SHIFT</kbd> corri</span><span><kbd>SPACE</kbd> frena</span><span><kbd>ESC</kbd> pausa</span>';}
window.addEventListener('keydown',e=>{if(['KeyW','KeyA','KeyS','KeyD','ArrowUp','ArrowDown','ArrowLeft','ArrowRight','Space'].includes(e.code))e.preventDefault();if(e.repeat)return;if(e.code==='Enter'&&!state.started)start();if(!state.started)return;keys.add(e.code);if(e.code==='KeyE')toggleMount();if(e.code==='Escape'){state.paused=!state.paused;keys.clear();toast(state.paused?'Pausa':'Riprendi',2);}});window.addEventListener('keyup',e=>keys.delete(e.code));
const canvas=$('world');canvas.addEventListener('pointerdown',e=>{if(!state.started)return;drag={x:e.clientX,y:e.clientY,id:e.pointerId};canvas.setPointerCapture(e.pointerId);});canvas.addEventListener('pointermove',e=>{if(!drag||drag.id!==e.pointerId)return;camYaw-=(e.clientX-drag.x)*.005;camPitch=clamp(camPitch-(e.clientY-drag.y)*.003,-.25,.9);drag={x:e.clientX,y:e.clientY,id:e.pointerId};});for(const ev of ['pointerup','pointercancel','lostpointercapture'])canvas.addEventListener(ev,e=>{if(drag?.id===e.pointerId)drag=null;});
$('touchCar').onclick=toggleMount;document.querySelectorAll('[data-key]').forEach(b=>{b.addEventListener('pointerdown',e=>{e.preventDefault();keys.add(b.dataset.key);b.setPointerCapture(e.pointerId);});for(const ev of ['pointerup','pointercancel','lostpointercapture'])b.addEventListener(ev,()=>keys.delete(b.dataset.key));});
window.addEventListener('resize',()=>{if(!renderer)return;camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight);});

async function init(){setupIntro();try{progress(8,'Aprendo le cronache della città…');const [mapResponse,terrainResponse]=await Promise.all([fetch('./data/padova.json'),fetch('./data/terrain.json')]);if(!mapResponse.ok||!terrainResponse.ok)throw new Error('data');const raw=await mapResponse.json(),terrainData=await terrainResponse.json();data=periodData(raw);progress(34,'Ricostruendo strade e case entro le mura…');scene=new THREE.Scene();scene.background=new THREE.Color('#b9ae91');scene.fog=new THREE.Fog('#b9ae91',180,1050);camera=new THREE.PerspectiveCamera(58,innerWidth/innerHeight,.12,1300);renderer=new THREE.WebGLRenderer({canvas,antialias:true,powerPreference:'high-performance'});renderer.setSize(innerWidth,innerHeight);renderer.setPixelRatio(Math.min(devicePixelRatio,1.2));renderer.shadowMap.enabled=true;renderer.outputColorSpace=THREE.SRGBColorSpace;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.05;scene.add(new THREE.HemisphereLight('#e4d1a7','#65533f',2.2));const sun=new THREE.DirectionalLight('#ffd9a0',2.8);sun.position.set(-160,220,300);sun.castShadow=true;sun.shadow.mapSize.set(1024,1024);sun.shadow.camera.left=-80;sun.shadow.camera.right=80;sun.shadow.camera.top=80;sun.shadow.camera.bottom=-80;scene.add(sun,sun.target);terrain=new Terrain(terrainData,data);world=new CityWorld(scene,data,terrain);world.setQuality('medium');graph=makeRoadGraph(data.roads);player=createPerson('#79604a',2);accessory(player,'citizen');scene.add(player);state.y=terrain.height(state.x,state.z);player.position.set(state.x,state.y,state.z);progress(61,'Alzando mura, torri e porte…');buildPeriodCity();world.update(state.x,state.z,true);progress(78,'Aprendo mercati e botteghe…');populate();progress(94,'Mandando in strada cittadini, animali e guardie…');state.ready=true;$('playBtn').disabled=false;if($('play1500Btn'))$('play1500Btn').disabled=false;progress(100,'Pronta · Padova rinascimentale, ricostruzione stilizzata');requestAnimationFrame(animate);}catch(e){console.error(e);progress(100,'');$('loadingText').textContent='La modalità Galileo non è riuscita ad avviarsi. Ricarica la pagina.';$('playBtn').disabled=false;$('playBtn').textContent='Ricarica';$('playBtn').onclick=()=>location.reload();}}
init();
